<div class="page-heading"><span class="section-kicker">Kontrol akses</span><h1>Pengguna dan role</h1><p>Akun petugas baru menerima kata sandi sementara dan wajib menggantinya saat login pertama.</p></div><div class="row g-4"><div class="col-xl-4"><form class="data-panel" method="post" action="/admin/pengguna"><?= csrf_field() ?><h2 class="h5">Buat akun</h2><div class="mb-3"><label class="form-label" for="name">Nama</label><input class="form-control" id="name" name="name" required maxlength="150"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" name="email" type="email" required maxlength="190"></div><div class="mb-3"><label class="form-label" for="role_id">Role</label><select class="form-select" id="role_id" name="role_id" required><?php foreach ($roles as $role): ?><option value="<?= (int) $role['id'] ?>"><?= e($role['label']) ?></option><?php endforeach; ?></select></div><button class="btn btn-success" type="submit">Buat akun petugas</button></form></div><div class="col-xl-8"><section class="data-panel"><h2 class="h5 mb-3">Akun terbaru</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nama</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e($user['name']) ?></td><td><?= e($user['email']) ?></td><td><?= e($user['role_label']) ?></td><td><?= (int) $user['is_active'] ? 'Aktif' : 'Nonaktif' ?><?= (int) $user['must_change_password'] ? ' · wajib ganti sandi' : '' ?></td></tr><?php endforeach; ?></tbody></table></div></section></div></div>